#include "dfre/mission_event_markers.hpp"
#include "dfre/mission_event_memory.hpp"
#include "dfre/mission_sound_runtime.hpp"
#include "dfre/mission_tick.hpp"
#include "dfre/events.hpp"
#include <cstring>
#include <fstream>
#include <iostream>
#include <map>
using namespace dfre;using U=std::uint32_t;
namespace {
void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}template<class F>void fails(F f){bool stopped=false;try{f();}catch(const std::exception&){stopped=true;}check(stopped,"Required marker error did not stop");}
struct Bytes{std::map<U,unsigned char> bytes;void add(U at,U size){for(U i=0;i<size;++i)bytes[at+i]=0;}U get(U at,unsigned w){U value=0;for(U i=0;i<w;++i)value|=U(bytes.at(at+i))<<(i*8);return value;}void put(U at,unsigned w,U value){for(U i=0;i<w;++i)bytes.at(at+i)=static_cast<unsigned char>(value>>(i*8));}};
void basic(){constexpr U E=0x1300000,T=0x1301000,A=0x1302000,ALT=0x1303000,D=0x1304000,M=0x8ace80;Bytes bytes;bytes.add(0x4f2bc8,32);bytes.add(E,0x5000);bytes.add(M,0x22800);bytes.add(0x8cf900,4);bytes.put(0x4f2bcc,4,E);bytes.put(0x4f2bc8,4,1);bytes.put(0x8cf900,4,2);bytes.put(E+4,4,T);bytes.put(E+8,4,A);bytes.put(E+21,1,1);bytes.put(E+22,1,1);bytes.put(T+4,4,1);bytes.put(T+8,4,10);bytes.put(T+16,4,7);bytes.put(A+4,4,12);bytes.put(A+12,4,7);bytes.put(D+32,4,0x177d);for(U i=0;i<2;++i){bytes.put(M+i*0x114+4,4,D);bytes.put(M+i*0x114+0x7c,4,7);bytes.put(M+i*0x114+0x24,4,i?0x80000000u:0x7fffffffu);bytes.put(M+i*0x114+0x28,4,i?0x7fffffffu:0x80000000u);}
 MissionEventResourceBindings b;b.read=[&](U at,unsigned width){return bytes.get(at,width);};b.write=[&](U at,unsigned width,U value){bytes.put(at,width,value);};mission_event_markers_triggers(b);mission_event_markers_actions(b);for(U base:{T,A}){check(bytes.get(base+(base==T?16:12),4)==0x80000000u&&bytes.get(base+20,4)==0x80000000u&&bytes.get(base+24,4)==0x7fffffffu&&bytes.get(base+28,4)==0x7fffffffu,"Signed marker rectangle");}
 bytes.put(T+16,4,9);mission_event_markers_triggers(b);check(!bytes.get(T+4,4)&&!bytes.get(T+8,4),"Unmatched trigger clear");bytes.put(A+12,4,9);mission_event_markers_actions(b);check(!bytes.get(A+4,4)&&bytes.get(A+12,4)==9,"Unmatched action clear width");
 bytes.put(T+4,4,1);bytes.put(T+8,4,10);bytes.put(T+16,4,7);bool moved=false;b.read=[&](U at,unsigned width){const U value=bytes.get(at,width);if(at==M+0x7c&&!moved){moved=true;bytes.put(E+4,4,ALT);}return value;};mission_event_markers_triggers(b);check(bytes.get(T+16,4)==7&&bytes.get(ALT+16,4)==0x80000000u,"Current run pointer after marker read");
 bytes.put(E+4,4,T);unsigned writes=0;b.write=[&](U at,unsigned width,U value){bytes.put(at,width,value);if(++writes==2)throw std::runtime_error("Current write stop");};fails([&]{mission_event_markers_triggers(b);});check(writes==2&&bytes.get(T+16,4)==0x7fffffffu&&bytes.get(T+20,4)==0x80000000u,"Marker write failure prefix");fails([&]{mission_event_markers_actions({});});
}
void stock(const std::filesystem::path& folder){AssetStore assets(folder);MissionAssetCache cache(assets);const auto definitions=build_runtime_items(cache.items());std::vector<AiItemDefinition> ai_definitions;for(const auto& d:definitions)ai_definitions.push_back({d.id,d.flags,d.model,d.ai_data,d.move_data,static_cast<std::uint16_t>(d.hp)});std::ifstream file(folder/"Df.exe",std::ios::binary);AssetBytes exe((std::istreambuf_iterator<char>(file)),{});Fixed3 listener{};U yaw=0;MissionAudioFrameCells cells{0,listener,yaw};const TerrainGeometry* terrain=nullptr;MissionSoundRuntime sound(assets,exe,cells,terrain,{});const auto& raw=sound.asset_bindings();constexpr U D=0x18000000,M=0x8ace80;const U name=raw.call(0x497f60,{32,16,0,0});
 for(const std::string filename:{"C05M07.BMS","C06M01.BMS"}){const auto bytes=assets.read(filename).bytes;const auto mission=decode_mission(bytes);AiActorFactory factory(AiItemDefinitionTable(ai_definitions),{});AiActorTables tables;for(std::size_t i=0;i<mission.object_groups[2].size();++i)tables.groups[2].push_back(factory.convert(mission.object_groups[2][i],actor_handle(2,i)));MissionTickState state;init_mission_tick(state,{},std::move(tables),AiItemDefinitionTable(ai_definitions),factory.people().slots(),1);check(state.tables.groups[2].size()<=512,"Physical marker extent");unsigned marker_reads=0;MissionEventResourceBindings b;b.read=[&](U at,unsigned width)->U{if(at==0x8cf900){check(width==4,"Current marker count width");return U(state.tables.groups[2].size());}if(at>=M&&std::uint64_t(at)+width<=std::uint64_t(M)+0x22800){const U delta=at-M,slot=delta/0x114,offset=delta%0x114;check(slot<state.tables.groups[2].size()&&offset+width<=0x114,"Current marker physical row");++marker_reads;const auto& actor=state.tables.groups[2][slot];if(offset==4&&width==4)return actor.active?D+actor.definition_index*0x13c:0;const auto image=snapshot_mission_actor(state,{2,slot});U value=0;for(U i=0;i<width;++i)value|=U(image[offset+i])<<(i*8);return value;}if(at>=D&&std::uint64_t(at-D)+width<=definitions.size()*0x13c){const auto slot=(at-D)/0x13c,offset=(at-D)%0x13c;check(width==4&&offset==0x20,"Current definition field");return definitions.at(slot).id;}return raw.read(at,width);};b.write=raw.write;b.call=[&](U site,const std::vector<U>& args)->U{if(site==0x42eea0){check(args.empty(),"Trigger binder args");mission_event_markers_triggers(b);return 0;}if(site==0x42f020){check(args.empty(),"Action binder args");mission_event_markers_actions(b);return 0;}return raw.call(site,args);};MissionEventMemory memory(b);U objects=0;for(const auto& group:mission.object_groups)objects+=U(group.size());const U offset=268+objects*96+17408+2048+640;check(std::uint64_t(offset)+12+mission.events.size()*24+(mission.triggers.size()+mission.actions.size())*32==bytes.size(),"Actual event block extent");for(U i=0;i<=filename.size();++i)raw.write(name+i,1,i<filename.size()?U(filename[i]):0);EventStage expected;expected.load(mission);
 for(U iteration=0;iteration<2;++iteration){check(raw.call(0x499120,{name})!=0xffffffffu,"Actual BMS open");check(raw.call(0x4992d0,{offset,0})==offset,"Actual event seek");memory.load_current_file();raw.call(0x499020,{});for(U i=0;i<mission.triggers.size();++i)for(U w=0;w<8;++w)check(memory.trigger_at(i).read(w*4,4)==expected.trigger(i)[w],"Actual trigger binding differs");for(U i=0;i<mission.actions.size();++i)for(U w=0;w<8;++w)check(memory.action_at(i).read(w*4,4)==expected.action(i)[w],"Actual action binding differs");memory.reset();}check(marker_reads>0,"Actual marker owner was not read");std::cout<<filename<<": actual BMS/source arena/current converted group2 markers and reload passed\n";}
}
}
int main(int argc,char** argv){try{basic();if(argc==2)stock(argv[1]);else check(argc==1,"Usage: native_mission_event_markers [game-folder]");std::cout<<"Event marker checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
